import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  // We will need the internal collision logic for these tests, 
  // but since the requirement says only modify neon.js and neon.test.js,
  // and current neon.js doesn't export brickHit, we'll test via frame() 
  // or by adding it to the exports of neon.js.
  // Actually, the requirement says "do not change public API", but 
  // adding an export for testing purposes is usually okay if we don't 
  // change existing ones. However, I can just use the state.
} from './neon.js';

// Mock canvas for frame()
const mockCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- New tests for #1 Brick Bounce ---

import { frame } from './neon.js';

test('brick bounce: top face (flip vy)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving UP, hitting the BOTTOM face of the brick
  // Position it so it just entered the brick from below
  state.ball = { x: 150, y: 121, r: 7, vx: 0, vy: -200 }; 

  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'brick should be destroyed');
  assert.ok(state.ball.vy > 0, 'vy should be flipped to DOWN');
  assert.ok(state.ball.y > 120 + 7, 'ball should be pushed out of the brick');
});

test('brick bounce: bottom face (flip vy)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving DOWN, hitting the TOP face of the brick
  state.ball = { x: 150, y: 99, r: 7, vx: 0, vy: 200 };

  frame(mockCtx, state);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'vy should be flipped to UP');
  assert.ok(state.ball.y < 100 - 7, 'ball should be pushed out of the brick');
});

test('brick bounce: left face (flip vx)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving RIGHT, hitting the LEFT face of the brick
  state.ball = { x: 99, y: 110, r: 7, vx: 200, vy: 0 };

  frame(mockCtx, state);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx should be flipped to LEFT');
  assert.ok(state.ball.x < 100 - 7, 'ball should be pushed out of the brick');
});

test('brick bounce: right face (flip vx)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving LEFT, hitting the RIGHT face of the brick
  state.ball = { x: 201, y: 110, r: 7, vx: -200, vy: 0 };

  frame(mockCtx, state);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx > 0, 'vx should be flipped to RIGHT');
  assert.ok(state.ball.x > 200 + 7, 'ball should be pushed out of the brick');
});

test('brick bounce: corner hit (flip both)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving diagonally UP-RIGHT, hitting the bottom-left corner
  // x = 100 - 7 = 93, y = 120 + 7 = 127.
  // We place it exactly such that penetration is equal on both axes.
  state.ball = { x: 99, y: 121, r: 7, vx: 200, vy: -200 };

  frame(mockCtx, state);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx should be flipped to LEFT');
  assert.ok(state.ball.vy > 0, 'vy should be flipped to DOWN');
});

test('brick bounce: tunneling (sweep detection)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  // Ball is moving very fast. 
  // In one step it jumps from y=80 to y=130, skipping the brick (100-120).
  state.ball = { x: 150, y: 80, r: 7, vx: 0, vy: 1000 };

  // Since brick collision is currently in frame(), and frame() doesn't know about the previous position,
  // this test will currently FAIL unless we move collision to step() or implement sweeping.
  // The issue says "Sweep between the two positions". 
  // This means we need the position BEFORE the step.

  // For now, let's see if frame() handles it. It won't because it's discrete.
  // I will implement the fix and then this test should pass.

  // To properly test tunneling, I need to call step(state, dt) then frame(ctx, state).
  const dt = 0.05; // 50ms
  const oldY = state.ball.y;
  step(state, dt); // ball.y becomes 80 + 1000*0.05 = 130
  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'brick should be destroyed even if ball tunneled through');
  assert.ok(state.ball.vy < 0, 'ball should have bounced back');
});

