export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Tunnelling detection: check if the ball's path between frames 
    // crossed the brick.
    const prevX = state.ball.x - state.ball.vx * 0.016; // Approximation of last frame
    const prevY = state.ball.y - state.ball.vy * 0.016;

    // We'll use a simpler approach: the ball's current overlap is enough 
    // for most cases, but for tunneling, we'd actually need the actual 
    // previous position from step().
    // Since we can't easily change the API to pass the previous position to frame(),
    // we will check for intersection between the line (prevPos -> currentPos) 
    // and the brick's AABB.

    if (collides(state.ball, brick)) {
      // Collision resolution
      const overlapX = Math.min(state.ball.x + state.ball.r - brick.x, brick.x + brick.w - (state.ball.x - state.ball.r));
