test('brick bounce: top face (flip vy)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving UP, hitting the BOTTOM face of the brick
  state.ball = { x: 150, y: 121, r: 7, vx: 0, vy: -200 }; 

  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'brick should be destroyed');
  assert.ok(state.ball.vy > 0, 'vy should be flipped to DOWN');
  assert.ok(state.ball.y >= 120 + 7, 'ball should be pushed out of the brick');
});

test('brick bounce: bottom face (flip vy)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 100, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball moving DOWN, hitting the TOP face of the brick
  state.ball = { x: 150, y: 99, r: 7, vx: 0, vy: 200 };

  frame(mockCtx, state);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'vy should be flipped to UP');
  assert.ok(state.ball.y <= 100 - 7, 'ball should be pushed out of the brick');
});

